  "gizmo|real today, or real long ago, or pretend?": "audio/voice/gizmo/c98c00e6a1.mp3",
  "gizmo|megalodon.": "audio/voice/gizmo/4824454d10.mp3",
  "gizmo|real, long ago! megalodon is extinct. scientists learn about it from huge fossil teeth.": "audio/voice/gizmo/a67afa52ae.mp3",
